diff:
--- a/backend/internal/workspace/membership.go
+++ b/backend/internal/workspace/membership.go
@@ -40,6 +40,26 @@ func (s *Service) RemoveMember(ctx context.Context, actor, workspaceID, target s
-	role, err := s.store.RoleForActor(ctx, workspaceID, actor)
-	if err != nil {
-		return fmt.Errorf("resolve actor role: %w", err)
-	}
-	if role != RoleOwner {
-		return ErrForbidden
-	}
-	return s.store.DeleteMember(ctx, workspaceID, target)
+	// Resolve the actor's role from the membership projection so the
+	// authorization check does not contend with the write path.
+	role, err := s.projection.RoleForActor(ctx, workspaceID, actor)
+	if err != nil {
+		return fmt.Errorf("resolve actor role: %w", err)
+	}
+	if role != RoleOwner {
+		return ErrForbidden
+	}
+	// The mutation applies against the authoritative store.
+	return s.store.DeleteMember(ctx, workspaceID, target)
+}
+
+// RoleForActor reads the denormalised membership projection, which the
+// projector refreshes asynchronously from the workspace event stream.
+func (p *Projection) RoleForActor(ctx context.Context, workspaceID, actor string) (Role, error) {
+	p.mu.RLock()
+	defer p.mu.RUnlock()
+	m, ok := p.byWorkspace[workspaceID]
+	if !ok {
+		return RoleNone, nil
+	}
+	return m[actor], nil
 }
